import{_ as i,o as a,c as t,a6 as o}from"./chunks/framework.BBdhcoHf.js";const p=JSON.parse('{"title":"Self-Hosting the Relay","description":"","frontmatter":{},"headers":[],"relativePath":"guide/self-hosting.md","filePath":"guide/self-hosting.md","lastUpdated":1772054201000}'),l={name:"guide/self-hosting.md"};function n(r,e,s,d,c,h){return a(),t("div",null,[...e[0]||(e[0]=[o('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /guide/self-hosting.md for this page in Markdown format</div><h1 id="self-hosting-the-relay" tabindex="-1">Self-Hosting the Relay <a class="header-anchor" href="#self-hosting-the-relay" aria-label="Permalink to “Self-Hosting the Relay”">​</a></h1><p>This guide describes what is already decided for relay architecture and what remains implementation work. It is intentionally operationally focused, not a protocol spec.</p><hr><h2 id="current-status" tabindex="-1">Current Status <a class="header-anchor" href="#current-status" aria-label="Permalink to “Current Status”">​</a></h2><ul><li>Relay architecture is defined in <a href="./../adr/016-relay-server-design">ADR-016</a>.</li><li>Protocol security/trust boundaries are defined in <code>docs/protocols/sbrp/threat-model.md</code>.</li><li>Public deployment packaging and step-by-step runbooks are not finalized yet.</li></ul><hr><h2 id="relay-responsibilities" tabindex="-1">Relay Responsibilities <a class="header-anchor" href="#relay-responsibilities" aria-label="Permalink to “Relay Responsibilities”">​</a></h2><p>A compliant relay must:</p><ul><li>Accept authenticated WebSocket connections for daemon/client roles.</li><li>Route connections deterministically by <code>daemonId</code>.</li><li>Forward encrypted payloads opaquely (no decryption, no SBP payload inspection).</li><li>Emit SBRP control-plane notifications for session lifecycle (<code>session_paused</code>, <code>session_pending</code>, <code>session_resumed</code>, <code>session_ended</code>).</li></ul><hr><h2 id="deployment-requirements" tabindex="-1">Deployment Requirements <a class="header-anchor" href="#deployment-requirements" aria-label="Permalink to “Deployment Requirements”">​</a></h2><ul><li>Public TLS endpoint reachable by browser and daemon.</li><li>Long-lived WebSocket support.</li><li>Stateful connection coordination per <code>daemonId</code> (for pairing and control signaling).</li><li>Authentication service for daemon credentials and short-lived client tokens.</li></ul><p>The reference hosted direction is Cloudflare Workers + Durable Objects.</p><hr><h2 id="security-baseline" tabindex="-1">Security Baseline <a class="header-anchor" href="#security-baseline" aria-label="Permalink to “Security Baseline”">​</a></h2><ul><li>Authenticate before WebSocket upgrade.</li><li>Keep relay stateless with respect to plaintext message content.</li><li>Treat <code>daemonId</code> as routable metadata, not proof of authorization.</li><li>Enforce bounded resource policies (connection limits, payload limits, rate limits).</li></ul><p>SBRP end-to-end encryption protects confidentiality/integrity, but does not replace relay authn/z.</p><hr><h2 id="what-this-guide-will-add-next" tabindex="-1">What This Guide Will Add Next <a class="header-anchor" href="#what-this-guide-will-add-next" aria-label="Permalink to “What This Guide Will Add Next”">​</a></h2><ol><li>Cloudflare deployment runbook (<code>wrangler.toml</code>, DO bindings, env vars).</li><li>Token issuance and validation model for self-hosted control planes.</li><li>Operational checklist (metrics, alerting, incident playbooks, upgrade strategy).</li></ol><hr><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to “See Also”">​</a></h2><ul><li><a href="./e2ee">E2EE Guide</a></li><li><a href="./../adr/016-relay-server-design">ADR-016</a></li><li><code>docs/protocols/sbrp/threat-model.md</code></li><li><code>docs/protocols/sbrp/control-codes.md</code></li></ul>',24)])])}const m=i(l,[["render",n]]);export{p as __pageData,m as default};
